S['V3ConfigSyncItem'] = obj({
    **fieldnames('id kind_label title mr author meta'),
    'kind':string(enum=['runbook','alert_rule','agent_version','template']),
    'status':string(enum=['pending','imported','exported','merged'])},
    ['id','kind','kind_label','title','mr','author','meta','status'])
S['V3ConfigSyncList'] = obj({
    'direction':string(enum=['import','export']),
    'items':arr(ref('V3ConfigSyncItem'))}, ['direction','items'])
S['V3PromotionRequest'] = obj({'kind':string(enum=['template','templates','runbook','runbooks','alert_rule','alert-rules','agent_version','agents'],
    description='Canonical kinds are template, runbook, alert_rule and agent_version; plural UI aliases are accepted.'),
    'id':string(minLength=1,maxLength=200)}, ['kind','id'])
S['V3PromotionResult'] = obj(fieldnames('mr path'), ['mr','path'])
v3_route('get','/config-sync','List configuration promotion records or merged candidates',
    response=ref('V3ConfigSyncList'),
    desc='Read-only four-kind list for runbook, alert_rule, agent_version and sanitized canvas template. Non-production lists up to 100 signed persisted exports by the current authenticated actor in selected authorized environments. Current kind-specific access is rechecked after remote reads: Runbooks require the governed document lifecycle, team scope and recorded source revision; application-bound items require active application/environment bindings, and alert rules also allow the owner-team grant. Exported means a recorded open MR. Production requires a human platform administrator with global workspace.manage and reads a bounded, complete target-branch merged MR page, including promotions whose mutable label was removed. After remote reads, production rechecks global manager authority; both tiers recheck the exact live Cookie session and active account before returning the list. Before status merged or imported is reported, the exact single changed file at the immutable merge commit must match its kind-specific allowlisted path and trusted signed manifest; non-production merged status must also match the local export record. Imported requires a matching import ledger, persisted production target and successful audit for all four kinds. This read does not prove branch governance at merge time. Missing repository or source signing/trust configuration returns 501; unverifiable provenance returns 503; an over-limit list returns 413. Frontend state text and navigation require separate integration.')
v3_route('post','/promotions','Export a versioned sanitized configuration snapshot to a GitLab merge request',
    body=ref('V3PromotionRequest'),response=ref('V3PromotionResult'),
    desc='One selected non-production environment and current kind-specific source authorization are required. Template requires the active owner and canvas.change; runbook requires governed current published document/revision and knowledge.manage, including team scope; alert_rule requires an explicitly configured observed rule source and alert_rules.manage on its active application or owner team; agent_version requires agents.change and exports the source agent stable version. Each active application/environment binding is checked where applicable. The durable Ed25519-signed manifest contains source instance, environment, application, object ID, explicit source version and digest, plus only its bounded kind-specific safe snapshot. Template excludes node content and investigation evidence; runbook excludes body, command text and connectors; alert_rule excludes runtime state; agent_version includes a digest-pinned artifact reference but not prompt, tools or independently verified artifact bytes. Creates or reuses a fixed path, branch and MR in the separate configuration repository, with an audit record. An uncertain remote result returns 503 and a concurrent or changed export returns 409. Production returns 409 already_production; all returns 409 env_view_only. Unsupported kinds return 501 promotion_kind_unavailable; a missing alert source returns 501 promotion_source_unavailable; missing repository or signing configuration returns 501. This operation does not apply an alert rule or activate an agent.')
v3_route('post','/config-sync/{id}/import','Import a reviewed merged signed configuration snapshot',
    response=ref('V3ConfigSyncItem'),
    desc='id is mr-<positive IID>. Requires the production prod environment and a human platform administrator with global workspace.manage, rechecked inside the import transaction. The repository must prove the MR is merged with exactly one expected kind-specific changed file at its fixed merge commit; the bounded allowlisted manifest must verify against a configured trusted source public key. Import also requires current satisfied MR approval state, a distinct non-bot approver after the final diff version and before merge, and currently verifiable protected target-branch policy. API reads cannot prove the governance policy in force at merge time; deployment must retain that evidence. Template persists a sanitized canvas template; runbook persists a production governed draft without executable step content; alert_rule persists a declarative not_applied record without changing Prometheus; agent_version adds a catalog version without activating or changing rollout. Target, import ledger and success audit commit together. Repeated identical imports converge; target drift, unique conflicts and changed MR identity return 409 without partial import. Non-production and all return 409. Missing repository or trust configuration returns 501; unverifiable provenance returns 503.')
P['/promotions']['post']['responses']['422'] = {
    'description':'Invalid request, or a source object outside the export contract, refused before any export record or GitLab call (PA-96, PA-97): '
                  'template_has_description, template_retained_content, template_private_runbooks, template_structure_invalid, '
                  'alert_rule_expression_unsafe, alert_rule_label_not_exportable, alert_rule_not_exportable or artifact_ref_not_pinned. '
                  'An alert rule reason is given only after alert_rules.manage on its application or owner team.',
    'content':{'application/json':{'schema':ref('Error')}}}
for _method, _path in [('get','/config-sync'),('post','/promotions'),('post','/config-sync/{id}/import')]:
    P[_path][_method]['responses']['501'] = {
        'description':'Configuration repository, signing or source trust is unavailable; an observed kind source may be unconnected or the requested promotion kind unsupported',
        'content':{'application/json':{'schema':ref('Error')}}}
P['/config-sync']['get']['responses']['413'] = {
    'description':'Export or merged candidate list exceeds 100 items',
    'content':{'application/json':{'schema':ref('Error')}}}
